import{_ as t,o as r,c as n,O as e}from"./chunks/framework.db831a78.js";const d=JSON.parse('{"title":"AI 与大模型","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/11-AI大模型.md","filePath":"interview/后端/Java/11-AI大模型.md","lastUpdated":1787649265000}'),s={name:"interview/后端/Java/11-AI大模型.md"};function g(i,o,l,a,p,c){return r(),n("div",null,o[0]||(o[0]=[e('<h1 id="ai-与大模型" tabindex="-1">AI 与大模型 <a class="header-anchor" href="#ai-与大模型" aria-label="Permalink to &quot;AI 与大模型&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><blockquote><p>⚠️ <strong>本篇通用说明（重要）</strong>：我的主线项目（充电桩、T-CEC 互联互通、支付对账）<strong>目前还没上 AI 能力</strong>。所以这一章所有内容都按「<strong>学习方向 / 技术储备</strong>」对待，<strong>面试时绝对不要说成线上项目经历</strong>。 但我是有优势的：RAG 和 Agent 的后端落地用到的是 Spring Boot + SSE + 向量库，这些<strong>正好是我熟悉的技术栈</strong>。所以我的说法是「AI 这块我在学、也动手做过 demo，业务上还没落地，但我清楚后端要怎么做」。</p></blockquote><hr><h2 id="_1-大模型基础概念-llm、token、上下文窗口、temperature-★★★" tabindex="-1">1. 大模型基础概念：LLM、Token、上下文窗口、Temperature ★★★ <a class="header-anchor" href="#_1-大模型基础概念-llm、token、上下文窗口、temperature-★★★" aria-label="Permalink to &quot;1. 大模型基础概念：LLM、Token、上下文窗口、Temperature ★★★&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>LLM</strong>：基于 Transformer、在海量文本上预训练的模型，本质能力就是「预测下一个 token」，一个字一个字往外蹦（自回归）。</li><li><strong>Token</strong>：模型处理文本的最小单位，一个汉字大概 1-2 个 token，计费和上下文长度都按它算。</li><li><strong>上下文窗口</strong>：单次「输入 + 输出」的 token 上限，<strong>输出也占额度</strong>，超了就得截断或压缩。</li><li><strong>Temperature</strong>：随机性开关。越低越稳定（代码、事实问答用 0-0.3），越高越发散（写作、创意用 0.7-1）。</li></ul><p><strong>我的项目关联</strong><strong>说明一下</strong>：这是纯概念，我们项目里没用。我能关联的只有一点 —— 我们的<strong>日志/traceId 串链路</strong>思路和「上下文窗口」是同一种取舍：信息不能无限塞，得挑重点。</p><p><strong>面试答题话术</strong> 「我理解 LLM 就是自回归预测下一个 token，所以它有概率性。Token 是计费和上下文的基本单位，上下文窗口是输入输出合计。Temperature 控制随机性——做代码和事实问答要调到很低。这些都是概念，我们业务还没上，但我清楚成本主要按 token 算。」</p><hr><h2 id="_2-大模型幻觉-★★★" tabindex="-1">2. 大模型幻觉 ★★★ <a class="header-anchor" href="#_2-大模型幻觉-★★★" aria-label="Permalink to &quot;2. 大模型幻觉 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 模型一本正经地编造事实（假数据、假引用）。根因是它本质在「生成最像答案的内容」，不是查库，而且训练数据可能过时、有噪声。 缓解：RAG 喂真实资料、限定知识范围、Few-shot 给示例、降低 temperature、要求给依据、人工复核。<strong>幻觉不能彻底消除，只能缓解。</strong></p><p><strong>我的项目关联</strong><strong>说明一下</strong>：我们没上 AI，所以没有线上幻觉问题。但<strong>这个风险我很能理解</strong> —— 我们的 T-CEC 对接和支付对账都是「数据必须准」的场景，如果引入 AI 生成内容，一定要走 RAG + 溯源，绝不能让它自由发挥。这是我对 AI 落地到我们业务的判断。</p><p><strong>面试答题话术</strong> 「幻觉是模型编造内容，根因是它在生成而不是查询。缓解手段主要是 RAG 喂真实资料、降 temperature、要求给依据，但不能彻底消除。我们做的是计费对账这类要求数据准确的业务，所以我的判断是——AI 只能辅助，关键数据必须可溯源。」</p><hr><h2 id="_3-提示词工程-prompt-engineering-★★☆" tabindex="-1">3. 提示词工程（Prompt Engineering）★★☆ <a class="header-anchor" href="#_3-提示词工程-prompt-engineering-★★☆" aria-label="Permalink to &quot;3. 提示词工程（Prompt Engineering）★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 用输入设计引导输出。常用技巧：角色设定、Few-shot（给几个例子）、CoT 思维链（要求一步步想）、输出格式约束（JSON/Markdown）。 套路：明确任务 → 给上下文 → 给示例 → 限格式 → 要求依据。CoT 有效的原理是让模型展开中间推理，而不是直接跳结论。</p><p><strong>我的项目关联</strong><strong>说明一下</strong>：属于了解层面，项目里没用。日常我用 AI 辅助写代码、查资料，会用到这些技巧，但那不算项目经验，面试要老实说。</p><p><strong>面试答题话术</strong> 「提示词常用的是角色设定、Few-shot 和思维链。思维链有效是因为它逼模型展开推理而不是跳结论。这块我是日常用 AI 时练的，不算项目经验，但技巧和原理我都清楚。」</p><hr><h2 id="_4-rag-检索增强生成-★★★-【重点-后端最该掌握】" tabindex="-1">4. RAG 检索增强生成 ★★★ 【重点，后端最该掌握】 <a class="header-anchor" href="#_4-rag-检索增强生成-★★★-【重点-后端最该掌握】" aria-label="Permalink to &quot;4. RAG 检索增强生成 ★★★ 【重点，后端最该掌握】&quot;">​</a></h2><p><strong>通俗理解</strong><strong>RAG = 检索 + 增强 + 生成</strong>。为什么要它：模型没见过我们公司的私有文档、知识有截止时间、会幻觉、微调又贵。 完整流程五步：</p><ol><li><strong>切分</strong>：文档按语义/长度切成小片段（chunk）</li><li><strong>向量化</strong>：用 Embedding 模型把片段转成向量</li><li><strong>存储</strong>：写进向量库</li><li><strong>召回</strong>：把用户问题也向量化，按相似度（余弦）找 Top-K 最相关片段</li><li><strong>拼接生成</strong>：把召回的片段拼进 Prompt，交给 LLM 生成答案 细节：切片要有重叠（overlap）避免语义断裂；召回后可以用 Rerank 重排提升精度。</li></ol><p><strong>我的项目关联</strong><strong>这是我在重点学的方向，而且我能落地</strong>。如果给我们业务做，我的思路很具体：</p><ul><li>把<strong>充电桩接入文档、故障码表、T-CEC 协议规范、接入手册</strong>切分入库，做成<strong>运维/客服的知识库问答</strong>；</li><li>后端这块就是 Spring Boot + 向量库 + RAG 流程 + SSE 流式返回 —— <strong>技术栈我完全熟</strong>。 <strong>必须说清楚</strong>：这是我们业务还没落地的规划，不是线上功能，面试我会如实说「我在学、也做过 demo」。</li></ul><p><strong>面试答题话术</strong> 「RAG 的流程是：切分、向量化、存向量库、按语义召回 Top-K、拼进 Prompt 让模型生成。它的价值是解决私有知识和时效性问题。我把它当成一个具体项目的方向在看——我们充电业务有大量接入文档、故障码表、协议规范，很适合做运维知识库问答。后端这块就是 Spring Boot 加向量库加 SSE，栈我是熟的。要说明的是我们业务还没落地，这是我做的技术储备。」</p><hr><h2 id="_5-向量数据库-★★★" tabindex="-1">5. 向量数据库 ★★★ <a class="header-anchor" href="#_5-向量数据库-★★★" aria-label="Permalink to &quot;5. 向量数据库 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 传统库按「精确值」查，向量库按「语义相似」查，靠 ANN（近似最近邻）索引加速 —— HNSW（图索引）、IVF（倒排）、PQ（量化），牺牲一点精度换速度。 选型：Milvus（专业、大规模）、pgvector（PostgreSQL 插件，中小规模省心）、Redis Vector（已有 Redis 栈）、FAISS（偏库）。</p><p><strong>我的项目关联</strong><strong>真实背景</strong>：我们自己的业务库是 MySQL + InfluxDB（时序），<strong>还没引入向量库</strong>。选型上如果做我会倾向 pgvector —— 因为我们本来就是 MySQL 生态，运维成本最低，这个判断是基于我们真实技术栈得出的，不是我背的选型表。</p><p><strong>面试答题话术</strong> 「向量库和传统库的区别是——一个按语义近似查，一个按精确值查，底层靠 ANN 索引。选型我会优先看现有技术栈：我们主库是 MySQL，所以会优先考虑 pgvector，运维成本最低；数据量真上来了再换 Milvus。这个判断是从我们实际环境出发的。」</p><hr><h2 id="_6-function-calling-tool-use-agent-★★★" tabindex="-1">6. Function Calling / Tool Use / Agent ★★★ <a class="header-anchor" href="#_6-function-calling-tool-use-agent-★★★" aria-label="Permalink to &quot;6. Function Calling / Tool Use / Agent ★★★&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>Function Calling</strong>：模型不直接给答案，而是输出「要调哪个函数 + 参数」，由<strong>应用真正去执行</strong>，再把结果喂回模型继续生成。</li><li><strong>Agent</strong>：让模型自己规划、调工具、多步执行，核心是「思考 → 行动 → 观察」的循环（ReAct 模式）。</li><li><strong>关键分工</strong>：模型负责「决定调什么」，<strong>后端负责「真正执行 + 校验参数」</strong>。</li></ul><p><strong>我的项目关联</strong><strong>这里我有个特别的共鸣点</strong>：我们充电桩协议网关干的事，本质就是「解析指令 → 校验 → 执行 → 回结果」，跟 Function Calling 的模式非常像。所以我理解 Agent 的后端职责很快 —— <strong>模型是决策者，后端是执行者，安全性必须由后端兜住</strong>（不能把模型输出直接拼 SQL 或命令，这是<strong>通用安全原则</strong>）。</p><p><strong>面试答题话术</strong> 「Function Calling 是模型输出要调用的函数和参数，后端真正执行再回传结果。Agent 就是在这个基础上让模型多步循环——思考、行动、观察。我觉得后端在这块的核心职责是两件事：真正执行，以及<strong>校验参数、防注入</strong>。这点我们有共鸣，因为我们的协议网关也是『解析指令再校验执行』，模型输出绝对不能直接拼进 SQL 或命令里。」</p><hr><h2 id="_7-模型微调-fine-tuning-★★☆" tabindex="-1">7. 模型微调（Fine-tuning）★★☆ <a class="header-anchor" href="#_7-模型微调-fine-tuning-★★☆" aria-label="Permalink to &quot;7. 模型微调（Fine-tuning）★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 预训练是在通用语料上训底座，微调是在特定任务数据上继续训。<strong>LoRA</strong> 只训练注入的低秩矩阵、冻结原权重，大幅省显存和成本，是主流轻量方案。RLHF 是用人类偏好对齐模型输出。 <strong>选择原则</strong>：要引入私有知识、要能及时更新 → RAG；要稳定改变风格/格式/领域能力 → 微调。<strong>多数业务优先 RAG。</strong></p><p><strong>我的项目关联</strong><strong>了解层面</strong>。微调对我们不现实 —— 成本高、也没有标注数据。真有需求我会先上 RAG，这个判断是成本驱动的，不是技术偏好。</p><p><strong>面试答题话术</strong> 「微调是改模型本身，LoRA 是省显存的主流做法。选择上：私有知识、要更新就用 RAG；改风格和输出格式才考虑微调。对大多数业务来说 RAG 性价比更高，我们也是这个思路。」</p><hr><h2 id="_8-大模型应用工程-java-后端方向-★★★-【重点-最贴合我的栈】" tabindex="-1">8. 大模型应用工程（Java 后端方向）★★★ 【重点，最贴合我的栈】 <a class="header-anchor" href="#_8-大模型应用工程-java-后端方向-★★★-【重点-最贴合我的栈】" aria-label="Permalink to &quot;8. 大模型应用工程（Java 后端方向）★★★ 【重点，最贴合我的栈】&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>Spring AI</strong>：Spring 官方的 AI 框架，把各家模型（OpenAI、DeepSeek、通义、Ollama）统一成一套接口（ChatClient、EmbeddingModel），还封装了 VectorStore、提示词模板、Function Calling、RAG 流程、流式输出。跟 Spring Boot 无缝集成，starter 开箱即用。</li><li><strong>SSE 流式输出</strong>（重点）：模型生成慢，等整段返回体验差，所以用 SSE 边生成边推（打字机效果）。 <ul><li>实现：Controller 返回 <code>SseEmitter</code>，分片 <code>send()</code>、最后 <code>complete()</code>；或返回 <code>Flux&lt;ServerSentEvent&gt;</code>（WebFlux）。</li></ul></li><li><strong>SSE vs WebSocket</strong>：SSE 是<strong>单向</strong>（服务端推客户端）、基于 HTTP、能自动重连、更轻、好穿网关；WebSocket 是双向全双工。<strong>大模型场景只需要服务端单向推，所以 SSE 更合适。</strong></li><li><strong>网关注意</strong>：Nginx 要关缓冲（<code>proxy_buffering off</code>）、设长超时、加 <code>X-Accel-Buffering: no</code>，不然流式会被攒着一起发，打字机效果就没了。</li><li>其他工程点：token 成本控制（限 max_tokens、缓存 prompt）、多轮对话记忆（摘要压缩/滑动窗口）、超时重试降级（多模型冗余、限流）、内容安全（防 Prompt Injection）。</li></ul><p><strong>我的项目关联</strong><strong>这块是我最有底气的地方 —— 不是因为我做过 AI，而是因为技术栈完全对得上：</strong></p><ul><li><strong>SSE</strong>：我们后台的 <strong>3D 大屏实时刷新</strong>用的是 WebSocket（07 笔记讲过），所以我非常清楚「长连接推送」的工程问题 —— 超时、网关缓冲、断线重连。换成 SSE 做流式输出，我理解起来是同一个坑。</li><li><strong>Spring Boot + 异步/流式</strong>：Spring 全家桶（04 笔记）是我的主场。</li><li><strong>网关配置</strong>：我们的服务前面就有网关，<code>proxy_buffering</code> 这类配置我是真的处理过类似问题。 <strong>诚实声明</strong>：AI 应用本身还是我的学习储备，业务没上。</li></ul><p><strong>面试答题话术</strong> 「Java 做 AI 应用我会用 Spring AI，它把各家的模型统一成一套接口，还封装了 RAG 和流式输出。流式我用 SSE，Controller 返回 SseEmitter 分片推；选 SSE 而不是 WebSocket，是因为大模型只需要服务端单向推，SSE 更轻、更好穿网关。这里有个真实的坑——网关不关缓冲流式就失效了，会攒着一起发，我们做实时推送时踩过类似的问题。AI 应用本身我还在学习阶段，但这些工程细节我是有实战基础的。」</p><hr><h2 id="_9-常见-ai-面试速答-★★★-口述骨架" tabindex="-1">9. 常见 AI 面试速答 ★★★（口述骨架） <a class="header-anchor" href="#_9-常见-ai-面试速答-★★★-口述骨架" aria-label="Permalink to &quot;9. 常见 AI 面试速答 ★★★（口述骨架）&quot;">​</a></h2><p><strong>通俗理解</strong> 把高频问法串成几句话，面试时直接说骨架。</p><p><strong>我的项目关联</strong> 统一话术：<strong>AI 是我的技术储备方向，业务主线还没落地，但技术栈能对上（Spring Boot + SSE + 向量库）</strong>，这个定位要说在最前面，避免被追问「你线上 AI 项目的数据指标」时卡住。</p><p><strong>面试答题话术</strong></p><ul><li><strong>怎么做企业知识库问答</strong>：「文档切分 → Embedding → 向量库 → RAG 召回 → LLM 生成 → SSE 流式 → 加权限和内容安全，分阶段上线。我还在学习落地阶段。」</li><li><strong>RAG 和微调怎么选</strong>：「引入私有知识、要能及时更新用 RAG；改风格和领域能力才用微调。多数业务先 RAG。」</li><li><strong>怎么解决幻觉</strong>：「RAG、限定知识范围、Few-shot、降 temperature、要求给依据。不能彻底消除。」</li><li><strong>向量库为什么快</strong>：「靠 ANN 近似最近邻索引，HNSW、IVF 这些，牺牲一点精度换速度。」</li><li><strong>怎么保证 AI 服务高可用</strong>：「多模型冗余、超时重试、限流、缓存、降级兜底。」</li></ul><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>Transformer / 注意力机制</strong>：LLM 的底层架构，理解「自注意力让模型关注上下文相关部分」即可，面试问到不用展开公式。</li><li><strong>MoE（混合专家）</strong>：大模型省算力的架构思路，知道「按需激活部分专家」这个概念就行。</li><li><strong>多模态</strong>：模型能同时处理文本、图片、语音，了解概念即可。</li></ul>',58)]))}const h=t(s,[["render",g]]);export{d as __pageData,h as default};
